import {monsterFixture} from './monster-fixture.mjs';
import {ChallengeService} from '../../src/challenge/challenge-service.ts';
import {verifyRecoveryPages} from '../../../shared/src/public-state-proof.ts';
const h=await monsterFixture();h.clock.now=()=>1113;const q=await h.command([{kind:'basic',pressed:false}],10,'melee-demo');const calls=[];const measured=new ChallengeService({store:{run:fn=>h.store.run(async tx=>{const count={reads:0,writes:0};calls.push(count);return fn({get:async key=>{count.reads++;return tx.get(key);},set:(key,value)=>{count.writes++;return tx.set(key,value);}});})},clock:h.clock,identity:h.identity,content:h.content});const r=await measured.execute(q);if(r.outcome.status!=='committed')throw Error(JSON.stringify(r));const state=(await h.query()).data,pages=[];let total=1;for(let pageIndex=0;pageIndex<total;pageIndex++){const page=await h.service.query({...h.base,payload:{...h.base.payload,checkpointRevision:state.checkpointRevision,pageIndex}});pages.push(page);total=page.totalPages;}const proof=await verifyRecoveryPages(pages),player=proof.records.find(r=>r.kind==='actor'&&r.actorId===h.characterId),monsters=proof.records.filter(r=>r.kind==='monsterRuntime');console.log(JSON.stringify({profile:'local-test-monsters',rewards:'none',checkpointRevision:state.checkpointRevision,playerHp:player.hp,monsters:monsters.length,hostileDamageEvents:(await h.results('melee-demo')).filter(e=>e.kind==='damage'&&e.actorId!==h.characterId).length,transactions:calls,publicPages:pages.length,publicBytes:Buffer.byteLength(JSON.stringify(pages)),replay:(await h.service.execute(q)).replayed}));
